@login_required(login_url='login')
def uploadsydonia(request):
    user = request.user
    role = user.role_id

    if role == 1:
        template ='sydoniaupload.html'
        prompt = {'order': 'Attention a la disposition des colonnes'}

        if request.method == 'GET':
            return render(request, template, prompt)

        csv_file = request.FILES['file']

        if not csv_file.name.endswith('.csv'):
            messages.error(request, "Ceci n'est pas un fichier CSV")

        data_set = csv_file.read().decode('UTF-8')
        io_string = io.StringIO(data_set)
        next(io_string)
        for column in csv.reader(io_string, delimiter=':'):
            _, created = Paiement.objects.update_or_create(
                code_bur=column[0],
                bureau=column[1],
                modele=column[2],
                nif_importateur=column[3],
                importateur=column[4],
                nom_decl=column[5],
                n_liq=column[6],
                date_liq=column[7],
                ide_ser=column[8],
                ide_nbr = column[9],
                date_pay = column[10],
                tax_cod = column[11],
                mont_enc = column[12],
                bnk_nam = column[13],
                libelle = column[14],
                ref_pay = column[15],
                taux = column[16],
                qte_stat = column[17],
            )
        context = {}
        return render(request, template, context)
    else:
        return redirect('logout')


