                                mogasGOV=Sum('gov',
                                             filter=Q(idinspection__idcargaison__produit=2)),
                                jetGOV=Sum('gov',
                                           filter=Q(idinspection__idcargaison__produit=3)),
                                petroleGOV=Sum('gov',
                                               filter=Q(idinspection__idcargaison__produit=4)),
